function escapeHtml(v){return String(v||"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function sentences(text){return text.replace(/\\r/g,"").split(/(?<=[.!?;])\\s+|\\n+/).map(s=>s.trim()).filter(s=>s.length>10)}
function maskPII(text){return text.replace(/\\b\\d{12}\\b/g,"[ИИН скрыт]").replace(/\\b(?:\\d[ -]*?){16}\\b/g,"[КАРТА скрыта]").replace(/[\\w.+-]+@[\\w.-]+\\.[A-Za-z]{2,}/g,"[EMAIL скрыт]").replace(/(?:\\+7|8)[\\s()-]*\\d{3}[\\s()-]*\\d{3}[\\s-]*\\d{2}[\\s-]*\\d{2}/g,"[ТЕЛЕФОН скрыт]")}
function analyze(text){
 const masked=maskPII(text), blocks=sentences(masked), findings=[];
 for(const rule of rules){const excerpt=blocks.find(b=>rule.patterns.some(p=>p.test(b)));if(excerpt)findings.push({...rule,excerpt,confidence:rule.severity==="high"?0.94:0.86})}
 for(const [id,re,title,article,action] of required){if(!re.test(masked))findings.push({id:"missing-"+id,title:"Не найдено: "+title,severity:"attention",article,why:"В представленном тексте это условие не обнаружено. Отсутствие не доказывает нарушение, но создаёт неопределённость.",action,excerpt:"Условие не найдено в загруженном тексте.",confidence:.82})}
 const high=findings.filter(x=>x.severity==="high").length, score=Math.max(18,100-high*17-(findings.length-high)*7);
 return {createdAt:new Date().toISOString(),name:($("#contractFile")?.files?.[0]?.name||"Вставленный текст"),text:masked,findings,score,high};
}
