async function extractFile(file){
 if(file.size>10*1024*1024)throw new Error("Файл превышает 10 МБ.");
 if(file.name.toLowerCase().endsWith(".txt"))return file.text();
 if(file.name.toLowerCase().endsWith(".docx")){if(!window.mammoth)throw new Error("Модуль DOCX не загрузился.");const r=await window.mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()});return r.value}
 if(file.name.toLowerCase().endsWith(".pdf")){const pdfjs=await import("https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.8.69/pdf.min.mjs");pdfjs.GlobalWorkerOptions.workerSrc="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.8.69/pdf.worker.min.mjs";const pdf=await pdfjs.getDocument({data:await file.arrayBuffer()}).promise;let text="";for(let i=1;i<=pdf.numPages;i++){const p=await pdf.getPage(i),c=await p.getTextContent();text+=c.items.map(x=>x.str).join(" ")+"\\n"}return text}
 throw new Error("Поддерживаются PDF, DOCX и TXT.");
}
