 $("#sampleContract").addEventListener("click",()=>{text.value="Депозит не возвращается ни при каких обстоятельствах. Арендодатель вправе заходить в квартиру без предварительного уведомления. Арендатор оплачивает любой ремонт. Арендная плата может быть повышена арендодателем в любое время. Договор может быть расторгнут в одностороннем порядке без предупреждения.";status.textContent="Пример добавлен.";status.className="status success"});
